python -I -c "
import pathlib
for p in [r'docs/spec-001-feature/feature-specification.md', r'docs/spec-001-feature/tasks/T3-contract-test-matrix.md']:
    data = pathlib.Path(p).read_bytes()
    for i, line in enumerate(data.splitlines(True), 1):
        if b'\xe2\x80\xa8' in line or b'\xe2\x80\xa9' in line or (b\"'a b'\" in line) or (b'\"a b\"' in line) or b'\xef\xbb\xbf' in line or b'U+2028' in line or b'U+FEFF' in line:
            print(p, 'line', i, repr(line[:160]))
"

$files = @('docs/spec-001-feature/feature-specification.md','docs/spec-001-feature/tasks/T3-contract-test-matrix.md','docs/spec-001-feature/tasks/T1-core-analysis.md')
foreach ($f in $files) {
  $lines = [System.IO.File]::ReadAllLines((Resolve-Path $f))
  for ($i=0; $i -lt $lines.Count; $i++) {
    $l = $lines[$i]
    if ($l -match 'a b|2028|2029|FEFF|splitlines edge|mid-file|U\+0130|chars: 36') {
      $codes = ($l.ToCharArray() | ForEach-Object { if ([int]$_ -gt 127) { 'U+{0:X4}' -f [int]$_ } }) -join ','
      Write-Output ("{0}:{1}: [{2}] {3}" -f $f, ($i+1), $codes, $l.Trim())
    }
  }
}

$lines = [System.IO.File]::ReadAllLines((Resolve-Path 'docs/spec-001-feature/review-development-project-manager.md'))
foreach ($n in 17) {
  $l = $lines[$n-1]
  $codes = ($l.ToCharArray() | ForEach-Object { if ([int]$_ -gt 127) { 'U+{0:X4}' -f [int]$_ } }) -join ','
  Write-Output ("line {0} nonascii: [{1}]" -f $n, $codes)
  $m = [regex]::Matches($l, 'escapes.{0,40}')
  foreach ($x in $m) { Write-Output ('MATCH: ' + ($x.Value -replace [string][char]0xFEFF, '<FEFF>' -replace [string][char]0x212A, '<212A>')) }
}
$g = $lines | Where-Object { $_ -like '*Wrong literals*' }
Write-Output ('GAPS: ' + (($g -replace [string][char]0xFEFF, '<FEFF>' -replace [string][char]0x212A, '<212A>')))

$path = 'docs/spec-001-feature/review-development-project-manager.md'
$text = [System.IO.File]::ReadAllText($path)
$k = [string][char]0x212A
$feff = [string][char]0xFEFF
$fixes = @(
  @{ old = 'to' + $k + 'en table (F4)'; new = 'token table (F4)'; tag = 'token-word' },
  @{ old = 'Replace the two table literals with the explicit escapes `"' + $k + '"` and `"' + $feff + '"`'; new = 'Replace the two table literals with the six-character ASCII escapes spelled backslash-u212A and backslash-uFEFF'; tag = 'F4-fixcol' },
  @{ old = 'escapes `"' + $k + '"` and `"' + $feff + '"` in place of plain ASCII `' + $k + '` and U+200D'; new = 'escapes spelled backslash-u212A and backslash-uFEFF in place of the plain ASCII letter K and U+200D'; tag = 'gaps-item3' }
)
foreach ($f in $fixes) {
  if ($text.Contains($f.old)) { $text = $text.Replace($f.old, $f.new); Write-Output ($f.tag + ': replaced') }
  else { Write-Output ($f.tag + ': NOT FOUND') }
}
[System.IO.File]::WriteAllText($path, $text)
# verify
$l2 = [System.IO.File]::ReadAllLines($path)
$bad = 0
for ($i=0; $i -lt $l2.Count; $i++) {
  if ($l2[$i].Contains($k) -or $l2[$i].Contains($feff)) { $bad++; Write-Output ('REMAINING invisible/kelvin on line ' + ($i+1)) }
}
Write-Output ('lines with raw U+212A/U+FEFF: ' + $bad)
foreach ($n in 17) { Write-Output ('line 17 tail: ' + $l2[$n-1].Substring($l2[$n-1].Length - 220)) }
Write-Output ($l2 | Where-Object { $_ -like '*Wrong literals*' })

$path = 'docs/spec-001-feature/review-development-project-manager.md'
$l2 = [System.IO.File]::ReadAllLines($path)
$l = $l2[58]
$chars = $l.ToCharArray()
$sb = New-Object System.Text.StringBuilder
for ($i=0; $i -lt $chars.Count; $i++) {
  $c = $chars[$i]
  if ([int]$c -gt 127) { [void]$sb.Append(('[' + ('U+{0:X4}' -f [int]$c) + ']')) } else { [void]$sb.Append($c) }
}
Write-Output ('LINE59(' + $chars.Count + ' chars): ' + $sb.ToString())
# also check line 17 for any remaining issues
$l17 = $l2[16]
$chars = $l17.ToCharArray()
$sb = New-Object System.Text.StringBuilder
for ($i=0; $i -lt $chars.Count; $i++) {
  $c = $chars[$i]
  if ([int]$c -gt 127) { [void]$sb.Append(('[' + ('U+{0:X4}' -f [int]$c) + ']')) }
}
Write-Output ('LINE17 nonascii map: ' + $sb.ToString())
